// CBSE 10 English Language and Literature, ch01 Reading Comprehension: Unseen Passages — question bank.
// Every passage, figure, survey, place description and name below is SOYL's own writing (passage_origin
// 'soyl-original'). No passage is taken or adapted from any book, newspaper, website, sample paper or past paper.
// All numbers in tables and charts are invented and captioned "illustrative data".
// Board pattern (blueprints/board.yaml, Section A): Q1 discursive passage 400–450 words (10 marks); Q2 case-based
// factual passage with visual input 200–250 words (10 marks). SOYL models each full passage as 8 parts: six 1-mark
// parts (MCQ, true/false, complete the sentence, find the word) and two 2-mark answers of about 30–40 words.
// Topics: t01 discursive passage · t02 case-based factual passage with visual input · t03 vocabulary in context.
import { Q, mcq, fb, short, tf, ar, match, ord, caseQ, child, table, bars } from '../../cbse-10-english-language-and-literature-ch02/src/lib.mjs';

const S2 = (o) => short({ marks: 2, wl: [30, 40], time: 150, ...o });
const S1 = (o) => short({ marks: 1, time: 60, ...o });
const SCHEME2 = [['Correct point taken from the passage (or the visual)', 1], ['Explanation or support in own words, about 30–40 words', 1]];
const SCHEME2E = [['A clear view or judgement', 1], ['Supported by a reason or detail from the passage', 1]];
const SCHEME1C = (what) => [[what, 1]];

const DISC = (title) => `Read the discursive passage **${title}** (a SOYL original, about 430 words) and answer the questions that follow.`;
const FACT = (title, vis) => `Read the factual passage **${title}** (a SOYL original) and study the ${vis} with it. Answer the questions that follow.`;
const MINI = (title, skill) => `Read the short passage **${title}** (a SOYL original) and answer the questions on ${skill}.`;

// ================================================================ Q1-type: discursive passages (10 marks each)
Q('dp_boredom', caseQ({
  t: [1, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  stem: DISC('In Praise of Doing Nothing'),
  passage: [
    '1. Ask a group of Class 10 students how they spent last Sunday and you are likely to hear a timetable: tuition in the morning, a coaching test after lunch, an hour of revision, and whatever was left over handed to a phone. Very few will say that they did nothing at all. Fewer still will say it without a trace of guilt.',
    '2. We have come to treat empty time as wasted time. Parents worry that an idle child is falling behind; schools fill the holidays with projects; and teenagers themselves reach for a screen the moment a conversation pauses or a bus is late. The result is a generation that is rarely bored, but also rarely alone with its own thoughts.',
    '3. That loss matters more than it seems. Boredom is uncomfortable precisely because it pushes the mind to look for something to do, and when no ready-made entertainment is available, the mind starts to make its own. A child staring out of a train window begins to invent stories about the people on the platform. A student with no plan for the afternoon may finally pick up the guitar gathering dust in the corner. Many people who are good at solving problems say that their best ideas came not at the desk but on a walk, in the shower or while waiting for something else.',
    '4. Unstructured time also teaches a quieter skill: the ability to manage one\'s own attention. When every minute is scheduled by someone else, a young person learns to follow instructions efficiently. When an afternoon is truly free, the same person has to decide what is worth doing, notice when interest fades, and choose again. These are the habits of an independent adult, and they cannot be learnt from a timetable.',
    '5. None of this means that structure is the enemy. Practice, coaching and revision are essential, especially in a board year, and a completely aimless routine would be as unhealthy as a crowded one. The argument is about balance. A schedule with no gaps leaves no room for the mind to wander, and wandering, it turns out, is where a great deal of thinking happens.',
    '6. So the next time you find yourself with half an hour and nothing to fill it, resist the urge to reach for your phone. Sit with the boredom for a while. Look out of the window, doodle in the margin of a notebook, or simply let your thoughts drift. You may be surprised by where they take you.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'What is the writer\'s main purpose in *In Praise of Doing Nothing*?', opts: ['to argue that young people need some unstructured time', 'to criticise coaching classes and tuition', 'to describe how students spend a typical Sunday', 'to warn that phones damage eyesight'], sol: 'Every paragraph builds the case for free, unscheduled time; the Sunday timetable is only the opening hook.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: According to paragraph 2, today\'s teenagers are rarely bored because …', model: 'they reach for a screen whenever there is a pause or a delay.', sol: 'Paragraph 2: any gap, such as a pause in conversation or a late bus, is filled with a screen.', scheme: SCHEME1C('Screens fill every pause (own words accepted)') })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', stem: 'How, according to the writer, does boredom lead to creativity? Answer in about 30–40 words.', model: 'Boredom is unpleasant, so it pushes the mind to find something to do. When no ready entertainment exists, the mind creates its own, like a child inventing stories at a train window or a student picking up a guitar.', sol: 'Point: discomfort drives the mind to act (paragraph 3). Support: one of the two examples.', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Which word best describes the tone of paragraph 5?', opts: ['balanced', 'angry', 'mocking', 'nostalgic'], sol: 'Paragraph 5 concedes that practice and coaching are essential and argues for balance, not for removing structure.' })),
    child('e', tf({ t: 1, d: 2, c: 'understanding', stem: 'True or false: the writer of *In Praise of Doing Nothing* believes that coaching and revision should be given up.', ans: false, sol: 'Paragraph 5 calls them essential; the writer wants gaps in the schedule, not an end to study.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'The writer says the habits of an independent adult cannot be learnt from a timetable. Do you agree? Give a reason in about 30–40 words.', model: 'Yes. A timetable only teaches us to follow someone else\'s plan. Deciding what is worth doing, noticing when interest fades and choosing again are skills we practise only when our time is truly our own.', sol: 'Either view earns marks if it is reasoned; link the reason to paragraph 4 (managing one\'s own attention).', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 3 that means *unpleasant or difficult to bear*: ___', acc: [['uncomfortable']], sol: 'Paragraph 3 calls boredom **uncomfortable**; it is an adjective, like the meaning given.' })),
    child('h', mcq({ t: 3, d: 2, c: 'application', stem: 'As used in paragraph 6 (*let your thoughts drift*), the word *drift* means…', opts: ['move along slowly without a fixed direction', 'sink slowly to the bottom', 'stop completely', 'speed up suddenly'], sol: 'Thoughts that drift wander freely, which is the writer\'s whole point about unplanned time.' })),
  ],
  sol: 'Skim for the argument (unstructured time is valuable), scan each paragraph for the detail asked, and keep 2-mark answers to about 30–40 words.',
}));

Q('dp_repair', caseQ({
  t: [1, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  stem: DISC('Mend It, Don\'t End It'),
  passage: [
    '1. In almost every Indian town there is a narrow shop, often no wider than a cupboard, where a man with a magnifying glass brings dead things back to life. Watches, mixers, radios, phones and pressure cookers arrive in plastic bags and leave working again, usually for less than the price of a cinema ticket. For generations this was simply how households treated their belongings: when something broke, you mended it.',
    '2. That habit is fading. Many modern gadgets are sealed shut with glue rather than screws, spare parts are hard to find, and a new model is advertised before the old one has been paid for. Faced with a cracked screen or a dead battery, buyers are often told that a repair will cost almost as much as a replacement. Some makers even warn that opening a device yourself will cancel its guarantee. So they shrug and buy new.',
    '3. The cost of that shrug does not appear on any bill. Every discarded device carries metals that were mined, refined and shipped across the world, and much of that material ends up in landfills or in informal recycling yards where workers, sometimes children, burn wires to recover copper. Electronic waste is among the fastest-growing kinds of rubbish on the planet, and most of it is never properly recycled.',
    '4. Repair offers a simple way to slow this flow. A phone that lasts five years instead of two sharply reduces how many new phones a household buys. Repair also keeps money and skills within the local economy. The person who fixes your fan is a neighbour, not a distant factory, and the knowledge in his hands was often passed down from a parent or an older master.',
    '5. In several countries, campaigners have begun to argue for a right to repair: manufacturers, they say, should sell spare parts, publish repair manuals and design products that can be opened with ordinary tools. Some governments have started to listen. Meanwhile, volunteers in many cities run repair cafés, where people bring broken items and learn to fix them alongside experienced helpers.',
    '6. Young people can play a part too. Before replacing something, ask whether it can be repaired, and if the answer is no, ask why. Learn to change a fuse, sew on a button or fit a bicycle chain; most of these skills can be picked up in an afternoon from a parent, a neighbour or the repair shop down the road. These small acts may not feel heroic, but each repaired object is one less item in a landfill and one more skill kept alive.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Why does the writer of *Mend It, Don\'t End It* begin with the small repair shop?', opts: ['to show that mending things was once a normal part of household life', 'to advertise a particular shop', 'to complain that repairs are too expensive', 'to prove that watches are hard to repair'], sol: 'The shop stands for a habit of mending that paragraph 2 says is now fading.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: Two reasons given in paragraph 2 for why modern gadgets are hard to repair are that …', model: 'they are sealed with glue instead of screws, and spare parts are difficult to find.', sol: 'Any two of: glued shut, scarce spare parts, repair costing almost as much as a new one.', scheme: SCHEME1C('Any two reasons from paragraph 2') })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', stem: 'What does the writer mean by saying that *the cost of that shrug does not appear on any bill*? Answer in about 30–40 words.', model: 'When people casually throw away a device, they pay nothing extra, but there is a hidden cost: mined metals are wasted, landfills grow, and poor workers, even children, breathe smoke while burning wires to recover copper.', sol: 'Point: a hidden environmental and human cost. Support: one detail from paragraph 3.', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Which of these is NOT given in the passage as a benefit of repair?', opts: ['It makes gadgets work faster than new ones.', 'It keeps money in the local economy.', 'It reduces the number of new phones bought.', 'It keeps traditional skills alive.'], sol: 'Paragraphs 4 and 6 give the other three; nothing is said about repaired gadgets being faster.' })),
    child('e', tf({ t: 1, d: 2, c: 'understanding', stem: 'True or false: according to *Mend It, Don\'t End It*, repair cafés are run by large manufacturers.', ans: false, sol: 'Paragraph 5 says volunteers run them.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'Which suggestion in paragraph 6 would be easiest for a student like you to follow, and why? Answer in about 30–40 words.', model: 'Asking whether something can be repaired is easiest. It needs no tools or training, only the habit of asking a question at the shop, and it can save money as well as keep one more gadget out of a landfill.', sol: 'Any one suggestion, with a practical reason linked to the passage.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 3 that means *thrown away as no longer wanted*: ___', acc: [['discarded']], sol: '**Discarded** devices are ones that have been thrown away.' })),
    child('h', mcq({ t: 3, d: 3, c: 'application', stem: 'In paragraph 3, *informal recycling yards* are yards that are…', opts: ['not officially organised or controlled', 'friendly and relaxed', 'open only at weekends', 'run by schools'], sol: 'Here *informal* means outside official rules, which is why unsafe practices such as burning wires happen there.' })),
  ],
  sol: 'Track the argument: a fading habit → its hidden cost → the benefits of repair → what campaigners and students can do.',
}));

Q('dp_languages', caseQ({
  t: [1, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  stem: DISC('The Gift of Many Tongues'),
  passage: [
    '1. A girl growing up in Bengaluru might speak Kannada with the vegetable seller, Tamil with her grandmother, Hindi with her friends from the next building and English in the classroom, all before dinner. Visitors from countries where most people speak a single language are often astonished by this. In India, it is simply an ordinary day.',
    '2. Yet many families quietly treat this richness as a problem to be solved. Parents who want their children to succeed sometimes stop speaking their home language at the dinner table, worried that it will slow down the child\'s English. Within a generation, a language that the grandparents spoke fluently may survive only in a few songs and a handful of kitchen words. Children grow up able to understand their grandparents but not to answer them, and talk across the generations shrinks to smiles and nods.',
    '3. The worry is understandable but largely mistaken. Researchers who study bilingual children have found that learning two or more languages does not confuse young minds; if anything, it seems to train them. A child who keeps switching between languages must track who understands what, and must hold back one set of words while using another. Many studies suggest that this practice helps attention and flexible thinking, although scientists still debate how large and lasting the benefits are.',
    '4. Other gains are easier to see. A person who speaks the language of a neighbourhood is trusted there in a way an outsider is not. A doctor who can explain an illness in a patient\'s own language is more likely to be understood and followed. A writer who moves between two languages can borrow images and sayings from each, enriching both. Businesses, too, value staff who can speak to customers in more than one language.',
    '5. Languages also carry memory. Proverbs, lullabies, recipes and the names people give to hills, rivers and plants often exist in only one tongue. When that tongue disappears, the knowledge it held does not simply move into English or Hindi; much of it is lost. Language experts warn that a large share of the world\'s roughly seven thousand languages could stop being spoken within this century.',
    '6. Learning English well and keeping a home language alive are not rival goals. Schools can value the languages children bring with them, and families can keep at least one meal a day in the language of the grandparents. Even a few songs, stories and games in the home language can carry it into the next generation. A country that speaks in many voices has nothing to apologise for. It has a treasure to protect.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which statement best expresses the central idea of *The Gift of Many Tongues*?', opts: ['Speaking several languages is an asset that families and schools should protect.', 'Children should learn English before any other language.', 'Bilingual children are always cleverer than others.', 'India should choose a single national language.'], sol: 'The passage defends multilingualism and ends by calling it a treasure to protect.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: Some parents stop speaking their home language at home because they fear that …', model: 'it will slow down their child\'s progress in English.', sol: 'Paragraph 2 gives this fear directly.', scheme: SCHEME1C('Fear that it will hold back English') })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', stem: 'According to paragraph 3, how does switching between languages exercise a child\'s mind? Answer in about 30–40 words.', model: 'The child has to keep track of which person understands which language and hold back one set of words while using another. This constant control seems to help attention and flexible thinking.', sol: 'Two mental tasks (tracking listeners, holding back words) + the likely benefit.', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 3, c: 'analysis', stem: 'What is the writer\'s attitude to the research on bilingual children?', opts: ['confident about the main finding but honest about the uncertainty', 'completely dismissive of it', 'unquestioningly enthusiastic about it', 'openly mocking of the researchers'], sol: 'The writer reports the finding but adds that scientists still debate how large and lasting the benefits are.' })),
    child('e', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which example in paragraph 4 shows that language builds trust?', opts: ['a person who speaks the language of the neighbourhood', 'a writer who borrows sayings from two languages', 'a grandmother who sings lullabies', 'a girl who speaks English in class'], sol: 'Paragraph 4 says such a person is trusted in a way an outsider is not.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'The writer says learning English and keeping a home language are *not rival goals*. Do you agree? Give one reason in about 30–40 words.', model: 'I agree. Many children already speak three or four languages every day without confusion, so a home language need not crowd out English. Each language serves a different part of life, and both can grow together.', sol: 'A view + a reason drawn from the passage (paragraph 1 or 3) or from experience.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 1 that means *greatly surprised*: ___', acc: [['astonished']], sol: 'Visitors are **astonished** by everyday multilingualism.' })),
    child('h', mcq({ t: 3, d: 3, c: 'application', stem: 'Which word is OPPOSITE in meaning to *rival* as used in paragraph 6?', opts: ['complementary', 'competing', 'hostile', 'separate'], sol: 'Rival goals compete; complementary goals support and complete each other.' })),
  ],
  sol: 'Note the move from a familiar scene to a worry, then to evidence that answers it, and finally to a call to action.',
}));

Q('dp_failure', caseQ({
  t: [1, 3], d: 3, c: 'evaluation', origin: 'soyl-original',
  stem: DISC('Why We Should Talk About Failure'),
  passage: [
    '1. Walk into any school assembly in the week after results and you will hear the names of toppers read out to applause. Nobody reads out the names of those who tried something difficult and fell short. This is natural, but it teaches a lopsided lesson: that success is the only story worth telling.',
    '2. Look closely at almost any achievement and you will find a long trail of failure behind it. A batter who scores a century has been dismissed cheaply many more times than the crowd remembers. A scientist who announces a discovery has usually spent years on experiments that went nowhere. Space agencies, India\'s among them, have lost rockets and spacecraft on the way to their goals, and have treated each loss as a lesson rather than a disgrace.',
    '3. Failure is useful because it gives information that success cannot. When a plan works, we rarely ask why; we simply repeat it. When it fails, we are forced to look for the weak link. A student who studies a poor test paper question by question learns far more than one who glances at the total and hides the paper in a drawer. Many top athletes watch recordings of their own defeats for exactly this reason.',
    '4. The difficulty is that failure hurts, and the hurt is often made worse by the people around us. A child who is laughed at for a wrong answer learns to stop raising her hand. A teenager who is compared unfavourably with a cousin learns that it is safer not to try than to try and fall short. Over time, such children choose easy tasks they are sure to finish rather than hard ones that might stretch them. Fear of failure, rather than failure itself, is what most often stops young people from growing.',
    '5. Schools and families can change this. Teachers can praise a thoughtful mistake as well as a correct answer. Parents can share stories of their own setbacks instead of presenting themselves as people who never stumbled. Students can keep a mistakes notebook in which every error is written down along with what it taught them. A school could even hold an assembly at which students and teachers each describe a failure and what they learnt from it.',
    '6. None of this means celebrating carelessness. A failure that comes from not preparing teaches very little except the obvious. The failures worth honouring are those that come from attempting something hard. If we want young people to attempt hard things, we must stop treating every stumble as a disaster and start treating it as part of the climb.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'What *lopsided lesson* do results-week assemblies teach, according to *Why We Should Talk About Failure*?', opts: ['that success is the only story worth telling', 'that toppers should not be praised', 'that difficult subjects should be avoided', 'that assemblies are a waste of time'], sol: 'Paragraph 1: only success is celebrated, so only success seems to matter.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: According to paragraph 3, failure is useful because …', model: 'it forces us to find the weak link, giving information that success cannot.', sol: 'Paragraph 3: success is simply repeated; failure makes us look for what went wrong.', scheme: SCHEME1C('It gives information / makes us find the weak link') })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', stem: 'Why, according to paragraph 4, do some young people stop trying? Answer in about 30–40 words.', model: 'They are afraid of failing because others make failure painful. A child laughed at for a wrong answer stops raising her hand, and a teenager compared with a cousin decides it is safer not to try at all.', sol: 'Point: fear of failure, made worse by others. Support: one or both examples.', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Why does the writer give the examples of the batter, the scientist and the space agencies in paragraph 2?', opts: ['to show that great achievements usually rest on many failures', 'to prove that sport is more difficult than science', 'to criticise space agencies for wasting money', 'to suggest that only famous people fail'], sol: 'All three examples support the claim that a long trail of failure lies behind achievement.' })),
    child('e', tf({ t: 1, d: 2, c: 'understanding', stem: 'True or false: the writer of *Why We Should Talk About Failure* argues that every kind of failure deserves praise.', ans: false, sol: 'Paragraph 6 excludes failure caused by carelessness or lack of preparation.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'Would keeping a mistakes notebook help you as a student? Give your view in about 30–40 words.', model: 'Yes. Writing down each error and its lesson would stop me repeating the same mistakes. Before a test I could revise from the notebook and see clearly which topics still need work.', sol: 'A personal view with a practical reason; it should connect to the passage\'s idea that failure carries information.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 4 that means *in a way that makes someone seem worse*: ___', acc: [['unfavourably', 'unfavorably']], sol: 'The teenager is compared **unfavourably** with a cousin; the meaning given works as an adverb, and so does the answer.' })),
    child('h', mcq({ t: 3, d: 2, c: 'application', stem: 'Which word from paragraph 6 is closest in meaning to *setback*?', opts: ['stumble', 'climb', 'attempt', 'carelessness'], sol: 'A stumble, like a setback, is a temporary failure on the way to a goal.' })),
  ],
  sol: 'Separate the writer\'s claim (failure teaches) from the limit placed on it (carelessness is not honoured).',
}));

Q('dp_trees', caseQ({
  t: [1, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  stem: DISC('Shade Is Not a Luxury'),
  passage: [
    '1. On a May afternoon in most Indian cities, the difference between a street lined with trees and a bare one is not a matter of opinion. You can feel it on your skin. Step out of the shade of a large neem or peepal onto open tar and the heat rises from the ground like the breath of an oven. Even birds and stray dogs know this, crowding under the few trees that remain.',
    '2. Trees cool a city in two ways. Their leaves block sunlight before it reaches roads, walls and roofs, which would otherwise soak up the heat and give it out slowly through the night. Trees also draw water from the soil and release it as vapour through their leaves, a process that takes heat from the surrounding air, much as sweat cools the body. A street under a full canopy can be several degrees cooler than one without.',
    '3. Yet trees are often the first casualties of growth. Roads are widened, footpaths are paved right up to the trunk, and old trees are cut to make room for flyovers and parking. Replacement saplings are planted in neat rows for photographs and then forgotten. Many die in their first summer for want of water and protection. And a sapling is no substitute for a lost giant: it takes decades to grow a canopy wide enough to shade a street.',
    '4. The choice of tree matters as much as the number. Some ornamental species brought from other continents look attractive in a brochure but give little shade, need more water and offer nothing to local birds and insects. Native trees such as neem, jamun, banyan and arjun have grown up with the local climate. Once established, they survive dry spells and support a web of life, from bees to barbets.',
    '5. Shade is also a question of fairness. Wealthier neighbourhoods tend to have parks and tree-lined avenues, while crowded settlements, where people can least afford air-conditioning, are often the hottest and barest. Planting trees there is not decoration. It is a public health measure that can reduce heat stress during long summers, when children, older people and outdoor workers such as street vendors suffer most.',
    '6. Citizens need not wait for the municipality. Housing societies can adopt a stretch of road; schools can plant native saplings and give students the duty of watering them through their first two summers; and anyone can object when a healthy old tree is marked for cutting. A tree planted today will not cool your street this year. But it may cool someone\'s street for the next hundred years.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'analysis', stem: 'Why does the writer of *Shade Is Not a Luxury* open with a May afternoon?', opts: ['to make the reader feel the difference that shade makes', 'to describe the writer\'s summer holiday', 'to prove that May is the hottest month everywhere', 'to complain about the cost of air-conditioning'], sol: 'The opening appeals to physical experience before any argument begins.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: According to paragraph 2, trees cool a city by …', model: 'blocking sunlight with their leaves and releasing water vapour that takes heat from the air.', sol: 'Both ways are needed for the mark: shade and the release of vapour.', scheme: SCHEME1C('Both ways: shade and vapour') })),
    child('c', S2({ t: 1, d: 3, c: 'understanding', stem: 'Why do many replacement saplings fail to survive, according to paragraph 3? Answer in about 30–40 words.', model: 'They are planted mainly for show, in neat rows for photographs, and then nobody looks after them. Without regular water and protection, many of the young plants die during their very first summer.', sol: 'Cause (planted for show, then neglected) + result (die for want of water and protection).', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Why does the writer prefer native trees such as neem and jamun?', opts: ['They suit the local climate and support local wildlife.', 'They grow faster than any other tree.', 'They look better in brochures.', 'They need no water at any stage.'], sol: 'Paragraph 4: they have grown up with the climate, survive dry spells once established and support birds and insects.' })),
    child('e', mcq({ t: 1, d: 2, c: 'understanding', stem: 'According to paragraph 5, which neighbourhoods are often the hottest?', opts: ['crowded settlements where people can least afford cooling', 'wealthy areas with parks', 'areas near rivers', 'new housing colonies on hills'], sol: 'The writer links heat to poverty and a lack of trees.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'How do the last two sentences of the passage strengthen the writer\'s argument? Answer in about 30–40 words.', model: 'They answer the obvious objection that trees grow too slowly to help. By admitting the delay and then pointing to a hundred years of shade, they make planting seem a generous gift to the future.', sol: 'Identify the objection being answered and the effect (long-term benefit, appeal to generosity).', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 3 that means *people or things harmed or destroyed by an event*: ___', acc: [['casualties']], sol: 'Trees are the first **casualties** of growth.' })),
    child('h', mcq({ t: 3, d: 3, c: 'application', stem: 'As used in paragraph 4 (*Once established, they survive dry spells*), *established* means…', opts: ['rooted and growing well in a place', 'officially founded', 'proved to be true', 'well known and respected'], sol: 'A tree that is established has settled into its spot and can cope on its own.' })),
  ],
  sol: 'Follow the argument: felt experience → how trees cool → why they are lost → which trees → fairness → what citizens can do.',
}));

Q('dp_libraries', caseQ({
  t: [1, 3], d: 3, c: 'evaluation', origin: 'soyl-original',
  stem: DISC('Do We Still Need Libraries?'),
  passage: [
    '1. When almost any fact can be found in seconds on a phone, it is fair to ask why towns still need public libraries. The question is not new. People asked it when radio arrived, and again when television did. Each time, libraries were expected to fade. Each time, they changed and survived.',
    '2. The first answer is that a library was never only a store of facts. A search engine is excellent at answering a question you already know how to ask. A library, especially its open shelves, is good at showing you questions you did not know existed. A student looking for a book on volcanoes may walk out with one on deep-sea creatures from the shelf beside it, and with a new interest. Browsing, the slow wandering along shelves without a fixed goal, is one of the oldest ways of learning, and one that a search box rarely allows.',
    '3. The second answer is that information online is plentiful but uneven. Some of it is careful and accurate; much of it is careless, out of date or written to sell something. Librarians are trained to tell the difference, and a good one can teach a young reader how to judge a source, a skill that matters more, not less, in a world flooded with information.',
    '4. Third, a library is one of the few indoor public spaces where nobody expects you to buy anything. In a crowded city it offers a quiet table, a fan, clean water and light to study by; in summer it is often one of the coolest rooms in the neighbourhood. For a student who shares a single room with a large family, that table can make the difference between passing and failing an examination.',
    '5. Libraries around the world have adapted to these needs. Many now lend laptops, run coding clubs, hold story hours for toddlers and help older people learn to use online services. In several Indian states, small community libraries run by volunteers have opened in villages, giving children their first chance to hold a storybook that is not a textbook. Some libraries send small vans of books to areas that have no library building at all.',
    '6. None of this happens by itself. Libraries need funding, trained staff and, above all, readers. The surest way to keep a library alive is to use it: to borrow a book, attend a reading, or simply sit and study there. A town that lets its library close does not only lose a building. It loses one of the few places where curiosity is free.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'analysis', stem: 'Why does the writer of *Do We Still Need Libraries?* mention radio and television in paragraph 1?', opts: ['to show that libraries have survived earlier predictions of their decline', 'to suggest that radio is better than books', 'to explain how libraries began', 'to argue that television harms reading'], sol: 'Each new medium was expected to finish libraries; each time they adapted.' })),
    child('b', S1({ t: 1, d: 2, c: 'understanding', stem: 'Complete the sentence appropriately: According to paragraph 2, a library\'s open shelves are good at …', model: 'showing readers questions and interests they did not know existed.', sol: 'Contrast with a search engine, which answers only the questions you already know how to ask.', scheme: SCHEME1C('Revealing unexpected questions or interests') })),
    child('c', S2({ t: 1, d: 3, c: 'analysis', stem: 'Why does the writer think librarians matter more today than before? Answer in about 30–40 words.', model: 'Online information is huge but mixed in quality, with much of it careless, old or selling something. Librarians can tell good sources from bad and teach young readers to judge sources for themselves.', sol: 'Point: uneven online information. Support: the librarian\'s skill of judging and teaching how to judge sources.', scheme: SCHEME2 })),
    child('d', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which need of students does paragraph 4 highlight?', opts: ['a quiet, free place to study', 'cheaper textbooks', 'faster internet', 'longer school holidays'], sol: 'For a student sharing one room with a large family, a quiet table matters.' })),
    child('e', tf({ t: 1, d: 3, c: 'analysis', stem: 'True or false: the writer of *Do We Still Need Libraries?* claims that all information found online is unreliable.', ans: false, sol: 'Paragraph 3 says some online information is careful and accurate; only much of it is unreliable.' })),
    child('f', S2({ t: 1, d: 4, c: 'evaluation', stem: 'Which of the writer\'s three answers do you find most convincing, and why? Answer in about 30–40 words.', model: 'The third answer convinces me most. A free, quiet and well-lit place to study can change a poor student\'s results, and neither a phone nor a search engine can offer that.', sol: 'Choose one answer (discovery, judging sources, free space) and give a reason.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 3 that means *available in large amounts*: ___', acc: [['plentiful']], sol: 'Online information is **plentiful** but uneven.' })),
    child('h', mcq({ t: 3, d: 2, c: 'application', stem: 'The phrase *flooded with information* (paragraph 3) suggests a world that is…', opts: ['overwhelmed by too much information', 'damaged by heavy rain', 'short of reliable news', 'cut off from the internet'], sol: 'A flood is too much of something; the metaphor stresses excess.' })),
  ],
  sol: 'The passage is organised as a question and three numbered answers, then examples and a call to action: use that structure to locate answers.',
}));

// ================================================================ Q2-type: case-based factual passages with visual input (10 marks)
export const vSleep = bars(
  { x: { min: 5, max: 13, label: 'Class' }, y: { min: 0, max: 10, label: 'Average sleep on a school night (hours)' }, label: 'Average sleep (hours)', points: [[6, 8.9], [7, 8.6], [8, 8.2], [9, 7.6], [10, 6.9], [11, 6.8], [12, 6.4]] },
  'Bar chart of average sleep on a school night by class: Class 6, 8.9 hours; Class 7, 8.6; Class 8, 8.2; Class 9, 7.6; Class 10, 6.9; Class 11, 6.8; Class 12, 6.4 hours.',
  'Average hours of sleep on a school night, survey of 1,200 students in six Lucknow schools (illustrative data)',
);
Q('fp_sleep', caseQ({
  t: [2, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  assets: [vSleep],
  stem: FACT('How Much Do Students Sleep?', 'bar chart'),
  passage: [
    'A survey of 1,200 students in six schools of Lucknow asked a simple question: how many hours do you usually sleep on a school night? The results, shown in the bar chart, suggest that sleep shrinks steadily as students move to higher classes.',
    'Students in Class 6 reported close to nine hours a night. By Class 9 the figure had fallen below eight, and in the board year, Class 10, it dropped to just under seven. Class 12 students slept the least of all. Health experts generally advise that teenagers need about eight to ten hours of sleep for growth, memory and mood, so most senior students in the survey fall well short.',
    'Asked what kept them awake, students most often named late tuition classes, homework and phones. Nearly half of the Class 10 respondents admitted using a phone in bed after the lights were off. Several said they slept longer on Sundays to catch up, although doctors point out that one long sleep at the weekend cannot fully repair a week of short nights.',
    'The survey team suggests a few small changes: a fixed bedtime, keeping phones out of the bedroom, and switching off screens an hour before sleep. They also urge schools not to schedule extra classes very early in the morning.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 2, d: 1, c: 'understanding', stem: 'According to the bar chart, students of which class slept the least?', opts: ['Class 12', 'Class 10', 'Class 11', 'Class 9'], sol: 'Class 12 has the shortest bar, at 6.4 hours.' })),
    child('b', fb({ t: 2, d: 1, c: 'understanding', stem: 'Complete the sentence: Class 10 students slept an average of ___ hours on a school night.', acc: [['6.9']], sol: 'The Class 10 bar reads **6.9** hours, which the passage describes as just under seven.' })),
    child('c', S2({ t: 2, d: 3, c: 'analysis', stem: 'Describe the overall trend shown in the chart, using two figures. Answer in about 30–40 words.', model: 'Sleep falls steadily as students move up the school. It drops from 8.9 hours a night in Class 6 to only 6.4 hours in Class 12, a loss of two and a half hours.', sol: 'Trend (steady fall with class) + two accurate figures with units; 8.9 − 6.4 = 2.5.', scheme: [['Overall trend stated (steady fall)', 1], ['Two accurate figures with units', 1]] })),
    child('d', mcq({ t: 2, d: 2, c: 'understanding', stem: 'Which of these is NOT named in the passage as something that kept students awake?', opts: ['noisy neighbours', 'late tuition classes', 'homework', 'phones'], sol: 'Paragraph 3 names tuition, homework and phones only.' })),
    child('e', tf({ t: 2, d: 3, c: 'analysis', stem: 'True or false: according to the chart and the experts\' advice in the passage, Class 8 students sleep within the recommended range.', ans: true, sol: 'Class 8 averages 8.2 hours, inside the advised eight to ten hours. This needs both the chart and the text.' })),
    child('f', S2({ t: 2, d: 4, c: 'evaluation', stem: 'Can sleeping longer on Sundays solve the problem the survey found? Answer in about 30–40 words, using the passage.', model: 'No. Doctors quoted in the passage say one long sleep at the weekend cannot fully repair a week of short nights. Students need regular sleep every night, for example through a fixed bedtime and no phones in bed.', sol: 'A judgement + the doctors\' point + one of the suggested remedies.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in the passage that means *people who answer a survey*: ___', acc: [['respondents']], sol: 'The Class 10 **respondents** answered the survey.' })),
    child('h', mcq({ t: 2, d: 2, c: 'application', stem: 'By how much does the average sleep of Class 6 students exceed that of Class 12 students?', opts: ['2.5 hours', '1.5 hours', '3.5 hours', '0.5 hours'], sol: '8.9 − 6.4 = 2.5 hours.' })),
  ],
  sol: 'Read the chart\'s axes and caption first, then use the passage for causes and advice; questions (e) and (h) need the figures.',
}));

export const vCycles = table(
  ['Month', 'Trips (thousand)', 'Docking stations'],
  [['January', '12', '20'], ['February', '18', '20'], ['March', '25', '35'], ['April', '21', '35'], ['May', '14', '35'], ['June', '9', '35']],
  'Table of the public bicycle scheme\'s first six months: January 12 thousand trips from 20 stations; February 18 thousand, 20 stations; March 25 thousand, 35 stations; April 21 thousand; May 14 thousand; June 9 thousand, all with 35 stations.',
  'Public bicycle scheme, first six months (illustrative data)',
);
Q('fp_cycles', caseQ({
  t: [2, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  assets: [vCycles],
  stem: FACT('Pedal Power: Six Months of a Bicycle Scheme', 'table'),
  passage: [
    'When a city of about ten lakh people launched a public bicycle scheme in January, many residents doubted that anyone would give up a scooter for a ride that needed pedalling. Six months on, the figures in the table tell a more interesting story.',
    'Riders unlock a bicycle at any docking station with a mobile app, ride it for up to an hour for a small fee and return it at any other station. In the first month, 12,000 trips were made from just 20 stations. As word spread and 15 new stations opened in March, monthly trips climbed to 25,000, more than double the January figure.',
    'The scheme then met its first real test: summer. With afternoon temperatures above 40 degrees, trips fell in April and dropped sharply in May. June brought the monsoon and the lowest figure of all, as riders avoided wet roads.',
    'Officials say the pattern is no cause for alarm. Most cities with bicycle schemes see seasonal ups and downs, and the real measure of success is whether riders return when the weather improves. To win them back, the city plans shaded cycle lanes on two main roads and covered stations near colleges. A survey of riders found that most used the bicycles for short trips to college, the market or a bus stop, journeys of under three kilometres.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 2, d: 1, c: 'understanding', stem: 'In which month did the bicycle scheme record the most trips?', opts: ['March', 'February', 'April', 'January'], sol: 'March has the highest figure, 25 thousand trips.' })),
    child('b', fb({ t: 2, d: 1, c: 'understanding', stem: 'Complete the sentence: In March, the number of docking stations rose from 20 to ___.', acc: [['35', 'thirty-five']], sol: 'The table shows **35** stations from March; the passage says 15 new stations opened.' })),
    child('c', S2({ t: 2, d: 3, c: 'analysis', stem: 'Using the table and the passage, explain why trips fell after March. Answer in about 30–40 words.', model: 'Trips fell because of the weather. Summer heat above 40 degrees cut trips to 21,000 in April and 14,000 in May, and monsoon rain in June brought the lowest figure, only 9,000.', sol: 'Cause from the passage (heat, then rain) + matching figures from the table.', scheme: [['Cause from the passage: heat, then rain', 1], ['Supported by accurate figures from the table', 1]] })),
    child('d', mcq({ t: 2, d: 2, c: 'understanding', stem: 'According to officials, what is the *real measure* of the scheme\'s success?', opts: ['whether riders return when the weather improves', 'the number of stations built', 'the total fees collected', 'the number of trips in June'], sol: 'Seasonal dips are expected; the test is whether riders come back.' })),
    child('e', tf({ t: 2, d: 2, c: 'understanding', stem: 'True or false: the bicycle scheme recorded fewer trips in June than in January.', ans: true, sol: 'June had 9 thousand trips, January 12 thousand.' })),
    child('f', S2({ t: 2, d: 4, c: 'evaluation', stem: 'Will the city\'s plans for shaded lanes and covered stations help the scheme? Give your view in about 30–40 words.', model: 'They should help. Trips fell sharply in the hot months, from 25,000 in March to 14,000 in May, so shade would make summer rides bearable, and covered stations would keep bicycles usable when it rains.', sol: 'A view + link to the cause of the fall + a supporting figure.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in the passage that means *happening at particular times of the year*: ___', acc: [['seasonal']], sol: 'Officials expect **seasonal** ups and downs.' })),
    child('h', mcq({ t: 2, d: 3, c: 'application', stem: 'By how many trips did the monthly figure fall from March to May?', opts: ['11,000', '4,000', '16,000', '7,000'], sol: '25,000 − 14,000 = 11,000 trips.' })),
  ],
  sol: 'Match each claim in the passage to a row of the table before answering; note the unit (thousand trips).',
}));

export const vWater = table(
  ['Activity', 'Share of daily household water use (%)'],
  [['Bathing', '27'], ['Flushing toilets', '24'], ['Washing clothes', '18'], ['Washing utensils', '13'], ['Drinking and cooking', '8'], ['Cleaning floors and vehicles', '6'], ['Plants and other uses', '4']],
  'Table of how household water was used: bathing 27 per cent, flushing toilets 24, washing clothes 18, washing utensils 13, drinking and cooking 8, cleaning floors and vehicles 6, plants and other uses 4 per cent.',
  'One-week water diary of 200 households in a Chennai neighbourhood (illustrative data)',
);
Q('fp_water', caseQ({
  t: [2, 3], d: 3, c: 'application', origin: 'soyl-original',
  assets: [vWater],
  stem: FACT('Where Does Our Water Go?', 'table'),
  passage: [
    'In the dry months, when tankers queue in narrow lanes and taps run for only an hour a day, water becomes the main topic of conversation in many Chennai homes. A residents\' association in one neighbourhood decided to find out where its water actually goes. Volunteers helped 200 households keep a simple diary of their water use for one week.',
    'The results surprised many families. On average, each person used about 150 litres a day, more than the 135 litres that city planners commonly treat as a reasonable daily need in urban homes. The table shows how that water was divided among different activities.',
    'Bathing and flushing toilets together took more than half of the total. Drinking and cooking, which most people had expected to be the largest share, used less than a tenth. Washing clothes came third.',
    'The association has since suggested a few low-cost changes. Families that switched from a shower to a bucket for bathing used noticeably less water, and a dual-flush button saves water with every flush. Waste water from home purifiers, usually poured down the drain, can be collected to mop floors or water plants. The volunteers say they are not asking anyone to suffer, only to notice. They plan to repeat the diary next summer to see whether habits have changed.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 2, d: 1, c: 'understanding', stem: 'According to the table, which activity used the largest share of household water?', opts: ['bathing', 'flushing toilets', 'washing clothes', 'drinking and cooking'], sol: 'Bathing, at 27 per cent, is the largest share.' })),
    child('b', fb({ t: 2, d: 2, c: 'application', stem: 'Complete the sentence: Bathing and flushing toilets together accounted for ___ per cent of water use.', acc: [['51', 'fifty-one']], sol: '27 + 24 = **51** per cent, which the passage calls more than half.' })),
    child('c', S2({ t: 2, d: 3, c: 'analysis', stem: 'How did the results differ from what families had expected? Answer in about 30–40 words, using a figure.', model: 'Families expected drinking and cooking to use the most water, but these took only 8 per cent, less than a tenth. Bathing and flushing toilets, which they had not considered, used over half between them.', sol: 'The expectation (drinking and cooking largest) + the actual figure + what really dominated.', scheme: [['The expectation and the actual result contrasted', 1], ['An accurate figure from the table', 1]] })),
    child('d', mcq({ t: 2, d: 2, c: 'understanding', stem: 'Why did the residents\' association ask households to keep a water diary?', opts: ['to find out where their water actually went', 'to fine families who used too much', 'to sell water purifiers', 'to plan a swimming pool'], sol: 'Paragraph 1 states the aim: to find out where the water goes.' })),
    child('e', tf({ t: 2, d: 2, c: 'analysis', stem: 'True or false: on average, each person in the neighbourhood used less water than the planners\' benchmark.', ans: false, sol: '150 litres a day is more than the 135-litre benchmark.' })),
    child('f', S2({ t: 2, d: 4, c: 'evaluation', stem: 'Which one suggested change would probably save the most water? Justify your choice with the table, in about 30–40 words.', model: 'Switching from a shower to a bucket would probably save the most, because bathing is the largest single use at 27 per cent. Even a small saving on the biggest share makes a large difference to the total.', sol: 'Pick a change and tie it to the size of the share it affects (bathing 27 or flushing 24 per cent).', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 1, c: 'application', stem: 'Find a word in the passage that means *people who offer their help without being paid*: ___', acc: [['volunteers']], sol: '**Volunteers** helped the households keep the diary.' })),
    child('h', mcq({ t: 2, d: 3, c: 'analysis', stem: 'What do the volunteers mean when they say they are asking people only to notice?', opts: ['Being aware of water use matters more than giving up comforts.', 'People should watch their neighbours.', 'Families should read their water bills.', 'Nobody needs to change anything.'], sol: 'Awareness, not hardship, is their aim; noticing leads to small changes.' })),
  ],
  sol: 'Percentages in the table add up to 100; combine rows when the question asks about two activities together.',
}));

export const vBirds = bars(
  { x: { min: 2018, max: 2026, label: 'Year' }, y: { min: 0, max: 16, label: 'Birds counted (thousand)' }, label: 'Migratory birds counted (thousand)', points: [[2019, 14.2], [2020, 15.1], [2021, 12.4], [2022, 11.0], [2023, 9.8], [2024, 10.6], [2025, 12.9]] },
  'Bar chart of winter bird counts at a wetland: 14.2 thousand in 2019, 15.1 thousand in 2020, 12.4 in 2021, 11.0 in 2022, 9.8 in 2023, 10.6 in 2024 and 12.9 thousand in 2025.',
  'Migratory birds counted each January at a wetland in central India (illustrative data)',
);
Q('fp_birds', caseQ({
  t: [2, 3], d: 3, c: 'analysis', origin: 'soyl-original',
  assets: [vBirds],
  stem: FACT('The Lake That Called the Birds Back', 'bar chart'),
  passage: [
    'Every winter, birds from Central Asia, Siberia and the Himalaya fly thousands of kilometres to spend the cold months on the lakes and marshes of India. Bird watchers at one wetland in central India have counted these visitors on the same January weekend every year since 2019. Their counts are shown in the bar chart.',
    'For the first two years the numbers were healthy, peaking at about 15,100 birds in 2020. Then came a worrying decline. New housing colonies were built along the northern shore, sewage began to flow into the lake, and a thick mat of water hyacinth spread across the open water where ducks once fed. By 2023 the count had fallen to 9,800, the lowest in the record.',
    'That year, the forest department and local volunteers began a restoration programme. They removed most of the hyacinth, built a small plant to treat sewage before it reached the lake, and marked a quiet zone where boats were not allowed in winter. The birds responded quickly. The count rose in 2024 and climbed to 12,900 in 2025.',
    'The bird watchers are cautiously hopeful. The numbers have not yet returned to their earlier level, and one good year can be followed by a bad one. Still, the recovery suggests that a damaged wetland can heal once the causes of the damage are removed.',
  ].join('\n\n'),
  parts: [
    child('a', mcq({ t: 2, d: 1, c: 'understanding', stem: 'In which year was the lowest number of birds counted at the wetland?', opts: ['2023', '2022', '2024', '2021'], sol: '2023 has the shortest bar, 9.8 thousand.' })),
    child('b', fb({ t: 2, d: 2, c: 'application', stem: 'Complete the sentence: Between 2020 and 2023, the bird count fell by ___ birds.', acc: [['5,300', '5300', 'about 5,300']], sol: '15,100 − 9,800 = **5,300** birds.' })),
    child('c', S2({ t: 2, d: 3, c: 'analysis', stem: 'Give two causes of the decline named in the passage, and show from the chart how serious it was. Answer in about 30–40 words.', model: 'Sewage flowed into the lake and water hyacinth covered the open water where ducks fed. As a result, the count fell from a peak of 15,100 in 2020 to just 9,800 in 2023.', sol: 'Two causes (housing on the shore, sewage, hyacinth) + the fall in figures.', scheme: [['Two causes from the passage', 1], ['The size of the fall shown with figures', 1]] })),
    child('d', mcq({ t: 2, d: 2, c: 'understanding', stem: 'Which action was part of the wetland\'s restoration programme?', opts: ['removing most of the water hyacinth', 'building new housing on the shore', 'allowing more boats in winter', 'feeding the birds every day'], sol: 'Paragraph 3 lists removing hyacinth, treating sewage and a quiet zone.' })),
    child('e', tf({ t: 2, d: 2, c: 'analysis', stem: 'True or false: the bird count in 2025 was higher than in 2019.', ans: false, sol: '12.9 thousand in 2025 is still below 14.2 thousand in 2019.' })),
    child('f', S2({ t: 2, d: 4, c: 'evaluation', stem: 'Why are the bird watchers only *cautiously* hopeful? Answer in about 30–40 words, using the chart.', model: 'The count has recovered to 12,900, but it is still below the 2019 and 2020 levels, and a single good year can be followed by a bad one. One rise does not yet prove lasting recovery.', sol: 'Two reasons: not back to the earlier level (with figures) + possible reversal.', scheme: SCHEME2E })),
    child('g', fb({ t: 3, d: 2, c: 'application', stem: 'Find a word in paragraph 3 that means *the act of bringing something back to a good condition*: ___', acc: [['restoration']], sol: 'The **restoration** programme began in 2023.' })),
    child('h', mcq({ t: 3, d: 2, c: 'application', stem: 'In paragraph 2, *a worrying decline* means…', opts: ['a fall that causes concern', 'a sudden rise', 'a polite refusal', 'a steady level'], sol: 'Decline as a noun means a fall or decrease.' })),
  ],
  sol: 'The chart gives the shape of the story (rise, fall, recovery); the passage gives the reasons for each stage.',
}));

