Q('mp_factopinion', caseQ({
  t: [1, 2], d: 3, c: 'evaluation', origin: 'soyl-original',
  stem: MINI('A Later School Bell', 'fact and opinion'),
  passage: 'In July, Sunrise Public School moved its morning bell from 7:30 to 8:30. Over the next term, attendance in the first period rose from 88 per cent to 94 per cent. The principal says the students look happier and more alert. Some parents, however, complain that the later finish clashes with afternoon tuition. In my view, every school in the city should follow this sensible example at once.',
  parts: [
    child('a', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which statement from *A Later School Bell* is a fact that could be checked?', opts: ['Attendance in the first period rose from 88 per cent to 94 per cent.', 'The students look happier and more alert.', 'Every school in the city should follow this example.', 'The later start is a sensible change.'], sol: 'Attendance records can be checked; the others are judgements.' })),
    child('b', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which statement in the passage is clearly the writer\'s own opinion?', opts: ['Every school in the city should follow this sensible example at once.', 'The bell moved from 7:30 to 8:30.', 'Some parents complain about tuition clashes.', 'The change was made in July.'], sol: '*In my view* and *should* mark an opinion.' })),
    child('c', tf({ t: 2, d: 3, c: 'analysis', stem: 'True or false: the passage proves that the later bell caused the rise in attendance.', ans: false, sol: 'The two happened together, but other reasons (the season, a new rule) are not ruled out; one term at one school is not proof.' })),
    child('d', S2({ t: 2, d: 4, c: 'evaluation', stem: 'Name one more piece of information you would want before agreeing with the writer, and say why. Answer in about 30–40 words.', model: 'I would want attendance figures from the same term last year. If attendance usually rises in that term anyway, the later bell may not be the reason, and other schools should not copy it too quickly.', sol: 'A relevant piece of evidence (last year\'s figures, other schools, students\' sleep, exam results) + why it matters.', scheme: SCHEME2E })),
  ],
  sol: 'A fact can be checked; an opinion judges or recommends. A rise that follows a change is not yet proof that the change caused it.',
}));

// ================================================================ standalone items: strategies and vocabulary
Q('mc_skim', mcq({ t: 1, d: 1, c: 'understanding', stem: 'You have thirty seconds to find out what an unseen passage is mainly about. What is the best way to read it?', opts: ['Skim the title, the first and last paragraphs and the first sentence of each paragraph.', 'Read every word slowly from the beginning.', 'Look only for difficult words.', 'Read the last line of each paragraph.'], sol: 'Skimming uses the parts where writers usually place the main idea: openings, topic sentences and the conclusion.' }));
Q('mc_scan', mcq({ t: 1, d: 2, c: 'understanding', stem: 'A question on an unseen passage asks in which year a dam was completed. What should you do?', opts: ['Scan the passage for a year written near the word *dam*.', 'Re-read the whole passage carefully from the start.', 'Guess from general knowledge.', 'Read only the first paragraph.'], sol: 'Scanning searches quickly for a specific detail, here a number near a keyword.' }));
Q('mc_topic_sentence', mcq({ t: 1, d: 1, c: 'recall', stem: 'In a well-organised paragraph of a discursive passage, the sentence that states the paragraph\'s main point is called the…', opts: ['topic sentence', 'concluding remark', 'supporting detail', 'counter-argument'], sol: 'The topic sentence, usually the first, states the main point; the rest supports it.' }));
Q('mc_infer', mcq({ t: 1, d: 2, c: 'application', stem: 'Read: *Ravi checked his watch for the fifth time and stared down the empty road.* What can you infer about Ravi?', opts: ['He is waiting impatiently for someone or something.', 'He has just bought a new watch.', 'He is lost and cannot find his way.', 'He enjoys looking at quiet roads.'], sol: 'Checking a watch repeatedly and watching the road are clues to impatient waiting; nothing is stated directly.' }));
Q('mc_tone_nostalgic', mcq({ t: 1, d: 2, c: 'application', stem: 'Read: *Those summer evenings on my grandmother\'s terrace, with the scent of jasmine and a radio playing somewhere below, will never come back.* The tone of this sentence is…', opts: ['nostalgic', 'sarcastic', 'indignant', 'objective'], sol: 'Fond memories of a past that is gone, with sensory details, create a nostalgic tone.' }));
Q('mc_tone_objective', mcq({ t: 1, d: 1, c: 'understanding', stem: 'Read: *The bridge is 1.2 kilometres long and was opened to traffic in March.* The tone of this sentence is…', opts: ['objective', 'humorous', 'anxious', 'bitter'], sol: 'It states checkable facts without any feeling or judgement.' }));
Q('mc_vocab_impasse', mcq({ t: 3, d: 3, c: 'application', stem: 'Read: *The talks reached an impasse; neither side would move an inch.* What does *impasse* mean here?', opts: ['a situation in which no progress is possible', 'a friendly agreement', 'a short break for tea', 'a written report'], sol: 'The clue after the semicolon (neither side would move) explains the word.' }));
Q('mc_vocab_gregarious', mcq({ t: 3, d: 3, c: 'application', stem: 'Read: *Unlike her gregarious brother, who loved parties, Anu preferred her own company.* What does *gregarious* mean?', opts: ['fond of the company of others', 'unkind to others', 'fond of being alone', 'very hard-working'], sol: 'The contrast word *Unlike* and the clue *who loved parties* show the meaning.' }));
Q('mc_clue_type', mcq({ t: 3, d: 2, c: 'understanding', stem: 'Read: *The herbivores, animals that eat only plants, gathered near the river.* Which kind of context clue explains *herbivores*?', opts: ['a definition clue', 'a contrast clue', 'an example clue', 'no clue at all'], sol: 'The phrase between the commas defines the word directly.' }));
Q('mc_main_idea', mcq({ t: 1, d: 3, c: 'analysis', stem: 'Read: *Many villages in Rajasthan have repaired old earthen ponds called johads. Rainwater collected in them soaks into the ground and raises the water table. Wells that had been dry for years now hold water again.* Which is the best title for this paragraph?', opts: ['Reviving a Traditional Way to Save Rainwater', 'The Deserts of Rajasthan', 'How Wells Are Dug', 'Why Villages Need Roads'], sol: 'The title must cover the whole paragraph: the old ponds, how they work and the result.' }));
Q('mc_pp', mcq({ t: 2, d: 3, c: 'application', stem: 'A chart in a factual passage shows that the share of students who walk to school fell from 40 per cent to 30 per cent. Which statement is accurate?', opts: ['It fell by 10 percentage points.', 'It fell by 10 per cent.', 'It fell by 30 percentage points.', 'It halved.'], sol: 'The gap between two percentages is in percentage points: 40 − 30 = 10 points (a 25 per cent fall in the share).' }));
Q('mc_chart_axes', mcq({ t: 2, d: 1, c: 'understanding', stem: 'A bar chart with a factual passage has years along the bottom and *Rainfall (mm)* on the side. What does the height of each bar show?', opts: ['the rainfall in millimetres in that year', 'the number of rainy days in that year', 'the temperature in that year', 'the year with the most rain'], sol: 'The vertical axis label names what the bar height measures, with its unit.' }));
Q('mc_fraction', mcq({ t: 2, d: 2, c: 'application', stem: 'A survey in a factual passage says that 200 of 800 students read a newspaper daily. Which phrase describes this most accurately?', opts: ['a quarter of the students', 'most of the students', 'a third of the students', 'half of the students'], sol: '200 ÷ 800 = 1/4, a quarter.' }));
Q('mc_qtype_eval', mcq({ t: 1, d: 2, c: 'understanding', stem: 'Which question on an unseen passage tests **evaluation** rather than recall?', opts: ['Do you agree with the writer\'s view? Give a reason.', 'In which year did the survey take place?', 'Find a word that means *small*.', 'Who is the writer of the passage?'], sol: 'Evaluation asks you to judge the writer\'s ideas and support your judgement.' }));
Q('mc_not_stated', mcq({ t: 1, d: 2, c: 'application', stem: 'An unseen-passage question asks which option is NOT mentioned in the passage. What is the safest method?', opts: ['Check each option against the passage and choose the one you cannot find.', 'Choose the longest option.', 'Choose the option you personally disagree with.', 'Choose the first option that sounds unfamiliar.'], sol: 'Eliminate the options that the passage does state; the one left is the answer.' }));
Q('mc_complete', mcq({ t: 1, d: 2, c: 'understanding', stem: 'A Section A question says *Complete the sentence appropriately.* What should your answer do?', opts: ['Continue the given words grammatically, using the idea from the passage.', 'Copy a whole paragraph from the passage.', 'Give your own opinion of the topic.', 'Write one word only, whatever the sentence needs.'], sol: 'The completion must fit the given start and carry the right information.' }));

Q('fb_skim_scan', fb({ t: 1, d: 1, c: 'recall', marks: 2, stem: 'Reading quickly for the general idea of a passage is called ___, while searching quickly for one specific detail is called ___.', acc: [['skimming'], ['scanning']], sol: 'General idea: **skimming**. Specific detail: **scanning**.', scheme: [['skimming', 1], ['scanning', 1]] }));
Q('fb_clue_word', fb({ t: 3, d: 2, c: 'application', stem: 'In the sentence *The tiny, almost minuscule, print was hard to read*, the word that helps you guess the meaning of *minuscule* is ___.', acc: [['tiny']], sol: '*Minuscule* is placed beside **tiny**, a synonym clue.' }));
Q('fb_points', fb({ t: 2, d: 2, c: 'understanding', stem: 'If a chart shows a rise from 25 per cent to 35 per cent, the rise is 10 percentage ___.', acc: [['points']], sol: 'The gap between two percentages is measured in percentage **points**.' }));
Q('fb_doubled', fb({ t: 2, d: 1, c: 'application', stem: 'If the number of visitors to a fair went from 3,000 to 6,000, we can say the number ___.', acc: [['doubled', 'has doubled']], sol: '6,000 is twice 3,000, so it **doubled**.' }));

Q('tf_tone_def', tf({ t: 1, d: 1, c: 'recall', stem: 'True or false: the tone of a passage is the writer\'s attitude to the subject, shown mainly through word choice.', ans: true, sol: 'Tone is attitude; adjectives, adverbs and images reveal it.' }));
Q('tf_fact', tf({ t: 1, d: 1, c: 'understanding', stem: 'True or false: *Pune is the best city in India for students* is a statement of fact.', ans: false, sol: 'It is an opinion: *best* is a judgement that cannot be checked.' }));
Q('tf_find_word', tf({ t: 3, d: 2, c: 'understanding', stem: 'True or false: when a question says *Find a word from the passage that means…*, any synonym from your own vocabulary will earn the mark.', ans: false, sol: 'The word must come from the passage (and usually from the paragraph named).' }));
Q('tf_correlation', tf({ t: 2, d: 3, c: 'analysis', stem: 'True or false: if a factual passage shows that ice-cream sales and swimming accidents both rise in summer, it proves that ice cream causes swimming accidents.', ans: false, sol: 'Two things rising together (often because of a third factor, hot weather) does not prove that one causes the other.' }));
Q('tf_two_mark', tf({ t: 1, d: 1, c: 'recall', stem: 'True or false: a 2-mark answer on an unseen passage should usually be about 30–40 words.', ans: true, sol: 'Short answers in Section A are meant to be brief: one point with support, in roughly 30–40 words.' }));

Q('ar_skim', ar({ t: 1, d: 2, c: 'understanding', a: 'Reading the first and last paragraphs of a discursive passage often reveals its main idea quickly.', r: 'Writers commonly state their main point in the introduction and return to it in the conclusion.', key: 'a', sol: 'Both are true, and the habit described in R is exactly why the method in A works.' }));
Q('ar_find_word', ar({ t: 3, d: 3, c: 'understanding', a: 'In a *find the word* question, the answer should be the same part of speech as the meaning given.', r: 'Examiners accept any word of similar meaning, even if it does not appear in the passage.', key: 'c', sol: 'A is true: a meaning given as an adjective needs an adjective. R is false: the word must come from the passage.' }));
Q('ar_axis', ar({ t: 2, d: 3, c: 'analysis', a: 'A bar that is twice as tall as another always shows a value exactly twice as large, whatever the scale.', r: 'Before comparing bars, a reader should check where the vertical axis starts and what units it uses.', key: 'd', sol: 'A is false: if the axis does not start at zero, heights mislead. R is true, and it is the reason A fails.' }));
Q('ar_tone_words', ar({ t: 1, d: 3, c: 'analysis', a: 'In *He merely smiled when we gave him the prize*, the word *merely* suggests that the writer expected a stronger reaction.', r: 'A single passage can contain more than one tone.', key: 'b', sol: 'Both are true, but R is a general point about passages and does not explain the effect of *merely* in A.' }));

Q('mt_strategies', match({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Match each reading strategy used in Section A with what it is best for.',
  pairs: [['Skimming', 'getting the general idea of a passage'], ['Scanning', 'finding a specific name, date or figure'], ['Close reading', 'answering inference and tone questions'], ['Using context clues', 'working out an unfamiliar word']],
  sol: 'Choose the strategy by the job: gist, detail, interpretation or meaning.',
}));
Q('mt_tones', match({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Match each tone word used in unseen-passage questions with its meaning.',
  pairs: [['sarcastic', 'mocking by saying the opposite of what is meant'], ['nostalgic', 'longing fondly for the past'], ['objective', 'factual and free of personal feeling'], ['apprehensive', 'worried about what may happen']],
  sol: 'Learn tone words in sets so that you can name an attitude precisely.',
}));
Q('mt_qskills', match({
  t: [1, 2], d: 3, c: 'analysis', marks: 2,
  stem: 'Match each Section A question with the skill it tests.',
  pairs: [['Which word in paragraph 2 means *ancient*?', 'vocabulary'], ['Why does the writer mention the space agencies?', 'the writer\'s purpose'], ['In which year was the count highest?', 'reading a chart'], ['What can you tell about the narrator\'s mood?', 'inference']],
  sol: 'Naming the skill tells you how to answer: find, explain, read off or infer.',
}));

Q('ord_plan', ord({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Arrange these steps for tackling a discursive unseen passage in the order SOYL recommends.',
  items: ['Read the questions to know what to look for.', 'Skim the passage for its main idea.', 'Find each answer and read the lines around it closely.', 'Write the answers in the order of the questions.', 'Check word limits, spelling and that every part is answered.'],
  sol: 'Questions first, then gist, then detail, then writing, then checking.',
}));
Q('ord_chart', ord({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'Arrange these steps for reading the visual input of a case-based factual passage.',
  items: ['Read the title and caption.', 'Check the labels and units.', 'Find the highest and lowest values.', 'Spot the biggest change.', 'Link what you found to the claims in the text.'],
  sol: 'From what the visual is about, to how it is measured, to its key features, to the text.',
}));

Q('sa_skim_scan', S2({ t: 1, d: 2, c: 'understanding', stem: 'Explain the difference between skimming and scanning an unseen passage, with one example of when you would use each. Answer in about 30–40 words.', model: 'Skimming means reading quickly for the general idea, for example to choose a title. Scanning means searching quickly for one detail, such as a date or figure asked for in a question.', sol: 'Define both + one use of each.', scheme: [['Both strategies correctly defined', 1], ['A suitable use for each', 1]] }));
Q('sa_infer_fridge', S2({ t: 1, d: 3, c: 'analysis', stem: 'Read: *The fridge held nothing but a single lemon, and the calendar on the wall still showed last month.* What can you infer about the people who live there? Give two clues. Answer in about 30–40 words.', model: 'They have probably been away, or too busy to look after the home. The almost empty fridge suggests nobody has shopped recently, and the calendar still on last month shows that nobody has turned the page.', sol: 'A sensible inference + two clues from the sentence.', scheme: [['A reasonable inference', 1], ['Two clues from the sentence', 1]] }));
Q('sa_tone_meeting', S2({ t: 1, d: 3, c: 'analysis', stem: 'Read: *Another urgent meeting, another hour of slides that nobody will remember.* Name the tone and justify it. Answer in about 30–40 words.', model: 'The tone is weary and mildly sarcastic. Repeating the word another shows boredom with something that keeps happening, and calling the meeting urgent while saying nobody will remember it mocks its importance.', sol: 'A tone word + evidence from the wording (repetition, contrast).', scheme: [['A suitable tone word', 1], ['Justified with words from the sentence', 1]] }));
Q('sa_vocab_strategies', S2({ t: 3, d: 2, c: 'understanding', stem: 'How can you work out the meaning of an unfamiliar word in an unseen passage without a dictionary? Give two strategies. Answer in about 30–40 words.', model: 'First, look for a clue in the nearby words, such as a definition, a synonym or a contrast. Second, try putting a simpler word in its place and check whether the sentence still makes sense.', sol: 'Two strategies (context clue, substitution, word parts, part of speech).', scheme: [['First strategy', 1], ['Second strategy', 1]] }));
Q('sa_fact_opinion', S2({ t: 1, d: 2, c: 'understanding', stem: 'Explain the difference between a fact and an opinion, using an example from a report on a school cricket match. Answer in about 30–40 words.', model: 'A fact can be checked, for example that the team won by twenty runs. An opinion is a personal judgement that others may dispute, such as calling the captain\'s innings the finest of the season.', sol: 'Definitions + one example of each in a cricket context.', scheme: [['Clear difference explained', 1], ['An example of each', 1]] }));
Q('sa_data_claim', S2({ t: 2, d: 4, c: 'evaluation', stem: 'A factual passage claims that *cycling to school has become far more popular*, but its table shows the share of students cycling rising from 12 per cent to 14 per cent. Does the table support the claim? Answer in about 30–40 words.', model: 'Only weakly. Cycling did rise, but by just two percentage points, from 12 to 14 per cent. Calling that far more popular exaggerates a small change, so the claim overstates what the table shows.', sol: 'A judgement + the size of the change in points + why the wording overstates it.', scheme: SCHEME2E }));
Q('sa_points_explain', S2({ t: 2, d: 3, c: 'analysis', stem: 'Explain why a rise from 20 per cent to 30 per cent should not be called a 10 per cent increase. Answer in about 30–40 words.', model: 'The gap between the two shares is 10 percentage points. As a proportion of the starting figure, though, the rise is 10 out of 20, which is an increase of 50 per cent, not 10 per cent.', sol: 'Percentage points (30 − 20 = 10) versus percentage change (10 ÷ 20 = 50 per cent).', scheme: [['Identifies the 10 percentage points', 1], ['Shows the 50 per cent relative increase', 1]] }));
Q('sa_main_idea', S2({ t: 1, d: 2, c: 'understanding', stem: 'Read: *Many hill towns now ban plastic bags. Shops offer paper or cloth bags instead, and visitors are fined for littering. As a result, streams that were once choked with waste are running clear again.* State the main idea in one sentence and give one supporting detail. Answer in about 30–40 words.', model: 'The main idea is that banning plastic bags has helped hill towns become cleaner. One supporting detail is that streams once blocked with waste now run clear, because shops use paper or cloth bags.', sol: 'One-sentence main idea + one detail that supports it.', scheme: [['Main idea in one sentence', 1], ['A relevant supporting detail', 1]] }));
Q('sa_rhetorical', S2({ t: 1, d: 3, c: 'analysis', stem: 'A discursive passage on screen time begins: *How many hours did you spend on your phone yesterday? Be honest.* Why might the writer open with a question? Answer in about 30–40 words.', model: 'The question pulls the reader in at once and makes the topic personal. Each reader starts counting their own hours, so they are already thinking about the problem before the writer begins to argue.', sol: 'Purpose of a rhetorical opening: engage the reader + make it personal.', scheme: [['Purpose identified (engage the reader)', 1], ['Effect explained (personal, prepares for argument)', 1]] }));
Q('sa_conclusion', S2({ t: 2, d: 4, c: 'evaluation', stem: 'In a survey of 100 students, 70 wanted longer library hours, 20 did not mind and 10 wanted shorter hours. Write a conclusion that a writer could fairly draw from these figures. Answer in about 30–40 words.', model: 'A clear majority of the students surveyed, seven in ten, would like longer library hours, while only one in ten wants them shorter. The school has good reason to consider extending the hours.', sol: 'A conclusion that stays within the figures (majority, 70 per cent) and avoids overclaiming (it is one survey of 100).', scheme: SCHEME2E }));
